"""Unit tests for ServiceConsumerLagObserver (OMN-12623)."""

import asyncio
import pytest

from subject import ServiceConsumerLagObserver


class _FakeTopicPartition:
    """Mimics aiokafka TopicPartition with .topic and .partition."""

    def __init__(self, topic: str, partition: int) -> None:
        self.topic = topic
        self.partition = partition

    def __hash__(self) -> int:
        return hash((self.topic, self.partition))

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, _FakeTopicPartition):
            return NotImplemented
        return (self.topic, self.partition) == (other.topic, other.partition)


class _FakeOffsetMeta:
    """Mimics OffsetAndMetadata with .offset."""

    def __init__(self, offset: int) -> None:
        self.offset = offset


class _FakeAdmin:
    """Fake ProtocolKafkaAdminLike for unit tests."""

    def __init__(
        self,
        committed: dict | None = None,
        end_offsets: dict | None = None,
        raise_on_list_offsets: Exception | None = None,
    ) -> None:
        self._committed = committed if committed is not None else {}
        self._end_offsets = end_offsets if end_offsets is not None else {}
        self._raise_on_list_offsets = raise_on_list_offsets
        self.list_consumer_group_offsets_calls: list[str] = []
        self.list_offsets_calls: list[dict] = []

    async def list_consumer_group_offsets(self, group_id: str) -> dict:
        self.list_consumer_group_offsets_calls.append(group_id)
        return self._committed

    async def list_offsets(self, request: dict) -> dict:
        self.list_offsets_calls.append(request)
        if self._raise_on_list_offsets is not None:
            raise self._raise_on_list_offsets
        return self._end_offsets


def _run(coro):
    return asyncio.get_event_loop().run_until_complete(coro)


@pytest.mark.unit
def test_observe_raises_value_error_on_empty_group_id():
    admin = _FakeAdmin()
    svc = ServiceConsumerLagObserver(admin)
    with pytest.raises(ValueError, match="non-empty"):
        _run(svc.observe(""))


@pytest.mark.unit
def test_observe_raises_value_error_on_none_group_id():
    admin = _FakeAdmin()
    svc = ServiceConsumerLagObserver(admin)
    with pytest.raises(ValueError, match="non-empty"):
        _run(svc.observe(None))


@pytest.mark.unit
def test_observe_returns_empty_lag_when_no_committed_offsets():
    admin = _FakeAdmin(committed={})
    svc = ServiceConsumerLagObserver(admin)
    result = _run(svc.observe("grp-1"))
    assert result.group_id == "grp-1"
    assert result.partition_offsets == ()


@pytest.mark.unit
def test_observe_computes_lag_for_single_partition():
    tp = _FakeTopicPartition("orders", 0)
    committed = {tp: _FakeOffsetMeta(100)}
    end_offsets = {tp: _FakeOffsetMeta(150)}
    admin = _FakeAdmin(committed=committed, end_offsets=end_offsets)
    svc = ServiceConsumerLagObserver(admin)
    result = _run(svc.observe("grp-1"))

    assert result.group_id == "grp-1"
    assert len(result.partition_offsets) == 1
    po = result.partition_offsets[0]
    assert po.topic == "orders"
    assert po.partition == 0
    assert po.committed_offset == 100
    assert po.log_end_offset == 150


@pytest.mark.unit
def test_observe_computes_lag_for_multiple_partitions_sorted():
    tp_a = _FakeTopicPartition("b-topic", 1)
    tp_b = _FakeTopicPartition("a-topic", 0)
    tp_c = _FakeTopicPartition("a-topic", 2)
    committed = {
        tp_a: _FakeOffsetMeta(10),
        tp_b: _FakeOffsetMeta(20),
        tp_c: _FakeOffsetMeta(30),
    }
    end_offsets = {
        tp_a: _FakeOffsetMeta(15),
        tp_b: _FakeOffsetMeta(25),
        tp_c: _FakeOffsetMeta(35),
    }
    admin = _FakeAdmin(committed=committed, end_offsets=end_offsets)
    svc = ServiceConsumerLagObserver(admin)
    result = _run(svc.observe("grp-1"))

    assert len(result.partition_offsets) == 3
    topics = [po.topic for po in result.partition_offsets]
    assert topics == ["a-topic", "a-topic", "b-topic"]
    partitions = [po.partition for po in result.partition_offsets]
    assert partitions == [0, 2, 1]


